xpath.script:
odoo.define('omnisync.dashboard.refresh', function (require) {
    "use strict";
    var core = require('web.core');
    var rpc = require('web.rpc');
    core.bus.on('web_client_ready', null, function () {
        setInterval(function () {
            rpc.query({route: '/omnisync/dashboard/metrics'}).then(function (data) {
                core.bus.trigger('omnisync_dashboard_update', data);
            });
        }, 60000);
    });
});
